#ifndef BONFYRE_ACCOUNT_CONNECTIONS_PRESENTATION_H
#define BONFYRE_ACCOUNT_CONNECTIONS_PRESENTATION_H
/* Read-only decoration of declared account links; no new account owner. */
#define BF_ACCOUNT_CONNECTION_STYLE \
"<style id=\"ak-connections-depth\">.external{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.external-item{display:flex!important;flex-direction:column;gap:12px!important;min-height:205px;padding:20px!important;animation:ak-connection-rise .48s both}.external-item:nth-child(2n){animation-delay:.08s}.connection-mark{display:grid;place-items:center;width:54px;height:54px;border-radius:16px;background:linear-gradient(135deg,#1a4834,#80af74);color:white;font:700 23px 'DM Sans',system-ui}.connection-body{display:grid;gap:6px;min-width:0}.connection-provider{color:var(--live);font:500 10px 'DM Mono',monospace;text-transform:uppercase;letter-spacing:.13em}.connection-body>a{font-size:19px!important;text-decoration:none}.connection-body>small{overflow-wrap:anywhere;color:var(--dim)}.connection-proof{align-self:start;display:inline-flex;align-items:center;gap:7px;border:1px solid var(--rule);border-radius:999px;padding:7px 11px;font:500 10px 'DM Mono',monospace}.connection-proof:before{content:'';height:7px;width:7px;background:var(--warm);border-radius:50%}.external-item[data-connection-proof=verified] .connection-proof:before{background:var(--live)}.connection-explainer{margin-top:auto!important;font-size:11px!important}.external-item .remove{position:absolute;top:14px;right:14px;background:var(--paper);border:1px solid var(--rule);border-radius:99px;padding:7px 10px}.external-item[hidden]{display:none!important}.connection-filters{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.connection-filters input{min-width:120px;flex:1;border-radius:12px;background:var(--paper)}.connection-filters select{padding:10px;background:var(--paper);color:var(--ink);border:1px solid var(--rule);border-radius:12px}.connection-count{color:var(--dim);font:500 11px 'DM Mono',monospace}@keyframes ak-connection-rise{from{opacity:0;transform:translateY(15px)}to{opacity:1;transform:translateY(0)}}@media(max-width:1100px){.external{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){.external-item{animation:none}}</style>"
#define BF_ACCOUNT_CONNECTION_SCRIPT \
"<script>(function(){const root=document.querySelector('#connections');if(!root)return;const bar=document.createElement('div');bar.className='connection-filters';bar.setAttribute('role','search');const q=document.createElement('input');q.type='search';q.placeholder='Find a linked identity';q.setAttribute('aria-label','Find a linked identity');const kind=document.createElement('select');kind.setAttribute('aria-label','Link verification');for(const [v,t] of [['all','All relationships'],['declared','Declared'],['verified','Verified']]){const o=document.createElement('option');o.value=v;o.textContent=t;kind.append(o)}const count=document.createElement('p');count.className='connection-count';count.setAttribute('aria-live','polite');bar.append(q,kind);root.before(bar,count);let working=false;function update(){if(working)return;working=true;try{for(const item of root.querySelectorAll('.external-item:not([data-enhanced])')){item.dataset.enhanced='1';const a=item.querySelector('a[href],b'),small=item.querySelector('small'),status=item.querySelector('.status');if(!a)continue;const parts=(small?.textContent||'').split(' · '),provider=parts[0]||'External',account=parts.slice(1).join(' · '),name=a.textContent.trim(),state=status?.textContent?.trim()||'Declared — not verified';item.dataset.connectionProof=state.toLowerCase()==='verified'?'verified':'declared';item.dataset.search=[provider,account,name].join(' ').toLowerCase();const mark=document.createElement('span');mark.className='connection-mark';mark.textContent=provider[0]?.toUpperCase()||'?';mark.setAttribute('aria-hidden','true');const body=document.createElement('div');body.className='connection-body';const providerLabel=document.createElement('span');providerLabel.className='connection-provider';providerLabel.textContent=provider;const accountLabel=document.createElement('small');accountLabel.textContent=account;a.textContent=a.tagName==='A'?name+' ↗':name;body.append(providerLabel,a,accountLabel);const badge=document.createElement('span');badge.className='connection-proof';badge.textContent=state;const form=item.querySelector('form');item.replaceChildren(mark,body,badge);if(form)item.append(form);const note=document.createElement('p');note.className='connection-explainer';note.textContent='Public relationship locator only; no provider authorization, import or action right is implied.';item.append(note)}const items=[...root.querySelectorAll('.external-item')],term=q.value.trim().toLowerCase(),filter=kind.value;let n=0;for(const item of items){item.hidden=!((item.dataset.search||'').includes(term)&&(filter==='all'||filter===item.dataset.connectionProof));if(!item.hidden)n++}count.textContent=items.length?n+' of '+items.length+' declared links shown':'No outside links have been declared'}finally{working=false}}q.addEventListener('input',update);kind.addEventListener('change',update);new MutationObserver(update).observe(root,{childList:true});update()})();</script>"
#endif
